def _child_config(state: StudioState) -> dict:
    return {"configurable": {"thread_id": f"{state['case_id']}:"
                                          f"{state['run_id']}"},
            "recursion_limit": 30}


def offline_agent(state: StudioState, checkpointer=None) -> dict:
    """Run the nested production graph with a scripted model."""
    from .scripted import ScriptedChatModel

    model = ScriptedChatModel(
        script_for(state["scenario"], state["case_id"], state["run_id"]))
    sub = build_agent(model=model, checkpointer=checkpointer)
    for key, point, times in _scenario_faults(state["scenario"],
                                              state["case_id"],
                                              state["run_id"]):
        _faults.inject(key, point, times)
    try:
        result = sub.invoke(_child_input(state), _child_config(state))
    except Exception as exc:
        return {"error": f"agent failed: {type(exc).__name__}: {exc}",
                "agent_trace": [], "agent_checkpoints": False}
    finally:
        _faults.clear()
    return {"agent_trace": _trace_messages(result),
            "agent_checkpoints": checkpointer is not None}

def live_agent(state: StudioState, checkpointer=None) -> dict:
    """Run the nested production graph with a budget-capped Gemini model.

    Transport retries are disabled (max_retries=0), so every request is
    exactly one attempt and the middleware cap means what it says.
    """
    from langchain.agents.middleware.model_call_limit import (
        ModelCallLimitMiddleware,
    )
    from langchain_google_genai import ChatGoogleGenerativeAI

    budget = state.get("budget")
    try:
        model_id = _require_live_config()
    except ConfigurationError as exc:
        return {"error": str(exc), "agent_trace": [],
                "agent_checkpoints": False}
    model = telemetry.maybe_wrap_gemini(
        ChatGoogleGenerativeAI(model=model_id, max_retries=0))
    sub = build_agent(
        model=model, checkpointer=checkpointer,
        extra_middleware=[ModelCallLimitMiddleware(run_limit=budget,
                                                   exit_behavior="error")])
    try:
        with neatlogs.trace(f"swapdesk-studio:{state['case_id']}",
                             kind="WORKFLOW") as span:
            span.set_attribute("swapdesk.case_id", state["case_id"])
            span.set_attribute("swapdesk.run_id", state["run_id"])
            span.set_attribute("swapdesk.mode", "live")
            span.set_attribute("swapdesk.budget", budget)
            result = sub.invoke(_child_input(state),
                                _child_config(state))
    except Exception as exc:
        return {"error": f"agent failed: {type(exc).__name__}: {exc}",
                "agent_trace": [], "agent_checkpoints": False}
    finally:
        telemetry.flush()
    return {"agent_trace": _trace_messages(result),
            "agent_checkpoints": checkpointer is not None}

def _snapshot_case(db_path: str, case_id: str) -> dict:
    """Best-effort persisted-state snapshot for diagnostics."""
    try:
        conn = connect(db_path)
    except Exception:
        return {}
    try:
        return {
            "exchanges": [dict(r) for r in conn.execute(
                "SELECT id, status FROM exchanges WHERE case_id = ?",
                (case_id,))],
            "operations": [dict(r) for r in conn.execute(
                "SELECT idempotency_key, op_type, status FROM operations "
                "WHERE case_id = ?", (case_id,))],
            "case": get_case(db_path, case_id),
        }
    except Exception:
        return {}
    finally:
        try:
            conn.close()
        except Exception:
            pass


def verify(state: StudioState) -> dict:
    """Derive the outcome from persisted state; render the reply."""
    ctx = _ctx_from(state)
    decided = derive_outcome(ctx)
    reply = render_reply(decided["outcome"], decided["data"])
    conn = connect(ctx.db_path)
    try:
        case_rows = [dict(r) for r in conn.execute(
            "SELECT * FROM exchanges WHERE case_id = ?", (ctx.case_id,))]
        case_ops = [dict(r) for r in conn.execute(
            "SELECT idempotency_key, op_type, status FROM operations "
            "WHERE case_id = ?", (ctx.case_id,))]
        case = get_case(ctx.db_path, ctx.case_id)
    finally:
        conn.close()
    resumed = bool(state.get("resume", False))
    evidence = {
        "mode": state.get("mode"),
        "label": WIRING_LABEL if state.get("mode") == "offline"
        else "live Gemini run",
        "resumed": resumed,
        # True resume needs agent checkpoints: without them the agent
        # re-executes over persisted business state (replay-safe, but a
        # fresh run, not a continuation).
        "agent_continued": resumed and bool(state.get("agent_checkpoints")),
        "outcome": decided["outcome"],
        "exchange_id": decided["exchange_id"],
        "reply": reply,
        "exchanges": case_rows,
        "operations": case_ops,
        "case_state": case["state"] if case else None,
    }
    return {"outcome": decided["outcome"], "reply": reply,
            "exchange_id": decided["exchange_id"], "evidence": evidence}


def error_terminal(state: StudioState) -> dict:
    """Terminal for failures: diagnostics preserved, stale fields cleared.

    Never renders a normal reply: outcome/reply/evidence stay empty so a
    failed attempt cannot masquerade as a result.
    """
    diagnostics = {
        "error": state.get("error"),
        "agent_trace": state.get("agent_trace", []),
        "resumed": bool(state.get("resume", False)),
    }
    if state.get("db_path") and state.get("case_id"):
        diagnostics["db"] = _snapshot_case(state["db_path"],
                                           state["case_id"])
    return {"diagnostics": diagnostics, "outcome": None, "reply": None,
            "exchange_id": None, "evidence": {}}

def _after_prepare(state: StudioState) -> str:
    return "error" if state.get("error") else "agent"


def _after_agent(state: StudioState) -> str:
    return "error" if state.get("error") else "verify"


def _builder(mode: str, checkpointer=None):
    def _prepare(state: StudioState) -> dict:
        # The graph defines the mode; input cannot smuggle the other one.
        return prepare({**state, "mode": mode})

    def _agent(state: StudioState) -> dict:
        if mode == "offline":
            return offline_agent(state, checkpointer)
        return live_agent(state, checkpointer)

    graph = StateGraph(StudioState)
    graph.add_node("prepare", _prepare)
    graph.add_node("agent", _agent)
    graph.add_node("verify", verify)
    graph.add_node("error", error_terminal)
    graph.set_entry_point("prepare")
    graph.add_conditional_edges("prepare", _after_prepare,
                                {"agent": "agent", "error": "error"})
    graph.add_conditional_edges("agent", _after_agent,
                                {"verify": "verify", "error": "error"})
    graph.add_edge("verify", END)
    graph.add_edge("error", END)
    return graph

def build_offline_graph(checkpointer=None):
    """Studio default: scripted model, zero model requests."""
    return _builder("offline", checkpointer).compile(
        checkpointer=checkpointer)


def build_live_graph(checkpointer=None):
    """Opt-in live Gemini with an explicit per-run request budget."""
    return _builder("live", checkpointer).compile(checkpointer=checkpointer)

