def _finalized_ok(messages) -> bool:
    """True once a finalize call has come back ok (history-aware stop)."""
    pending_finalize = False
    for m in messages:
        kind = type(m).__name__
        if kind == "AIMessage":
            pending_finalize = any(
                c.get("name") == "finalize_arranged"
                for c in (m.tool_calls or []))
        elif kind == "ToolMessage" and pending_finalize:
            pending_finalize = False
            try:
                import json as _json
                if _json.loads(m.content).get("ok"):
                    return True
            except ValueError:
                pass
    return False

