def _model_turns(messages) -> int:
    """Prior model requests: one AIMessage each (markers included, since
    each marks exactly one failed attempt)."""
    return sum(1 for m in (messages or [])
               if type(m).__name__ == "AIMessage")


class DeclaredBudgetMiddleware(AgentMiddleware):
    """Enforce the per-run request budget carried in state.

    Counts prior model turns from history, so the cap is exact per run
    across sync, async, and streaming paths (all funnel through these
    hooks), with no persistence to drift. Absent budget means
    unenforced. Breaches report with the platform's limit error text so
    the failure reads the same everywhere.
    """

    def _refuse(self, request):
        from langchain.agents.middleware.model_call_limit import (
            ModelCallLimitExceededError,
        )

        state = request.state or {}
        used = _model_turns(state.get("messages"))
        budget = state.get("budget")
        err = ModelCallLimitExceededError(used, used, None, budget)
        return AIMessage(content=f"{MODEL_FAILURE_MARKER} {err}")

    def _over(self, request) -> bool:
        state = request.state or {}
        budget = state.get("budget")
        if budget is None:
            return False
        return _model_turns(state.get("messages")) >= budget

    def wrap_model_call(self, request, handler):
        if self._over(request):
            return self._refuse(request)
        return handler(request)

    async def awrap_model_call(self, request, handler):
        if self._over(request):
            return self._refuse(request)
        return await handler(request)

class LazyGeminiModel(_BCM):
    """Builds the real Gemini model on first bind, not at import.

    Served graphs compile at import time, when credentials may be
