class ScenarioFaultMiddleware(AgentMiddleware):
    """Arm scenario faults just-in-time from run state.

    The recover scenario needs a crash on its reserve step. The key is
    dynamic (case:run), so a static fault table cannot work; instead this
    injects one-shot faults right before the matching tool runs. One-shot
    means no lifecycle to leak: replayed runs find saved results before
    any fault hook fires.
    """

    def _arm(self, request) -> None:
        from langchain.agents.middleware.types import AgentMiddleware as _AM

        _ = _AM
        state = request.state or {}
        if state.get("mode", "offline") != "offline":
            return
        if state.get("scenario") != "recover":
            return
        if request.tool_call.get("name") != "reserve_replacement":
            return
        _faults.inject(
            f"{state.get('case_id')}:{state.get('run_id')}:reserve",
            "crash", 1)

    def wrap_tool_call(self, request, handler):
        self._arm(request)
        return handler(request)

    async def awrap_tool_call(self, request, handler):
        self._arm(request)
        return await handler(request)

