    err = state.get("error") or _failure_text(state.get("messages", []))
    diagnostics = {
        "error": err,
        "agent_trace": _trace_messages(state.get("messages", [])),
        "resumed": bool(state.get("resume", False)),
    }
    if state.get("db_path") and state.get("case_id"):
        diagnostics["db"] = _snapshot_case(state["db_path"],
                                           state["case_id"])
    return {"diagnostics": diagnostics, "error": err, "outcome": None,
            "reply": None, "exchange_id": None, "evidence": {}}

